const MASCOT_IMAGE = "data:image/webp;base64,";

function Bot() {
  const mascot = useRef<HTMLButtonElement>(null);
  const body = useRef<SVGGElement>(null);
  const head = useRef<SVGGElement>(null);
  const face = useRef<SVGGElement>(null);
  const replyTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [greeting, setGreeting] = useState(false);
  const uid = useId().replace(/:/g, "");

  useEffect(() => {
    const button = mascot.current;
    if (!button) return;
    const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const nextCard = button.closest(".hero")?.nextElementSibling;
    let visible = false, frame = 0, previousTime = 0;
    const target = { x: 0, y: 0 }, current = { x: 0, y: 0 };
    const clamp = (value: number) => Math.min(1, Math.max(-1, value));

    function paint() {
      const { x, y } = current;
      body.current?.setAttribute("transform", `rotate(${(x * 1.5).toFixed(3)} 640 1020)`);
      head.current?.setAttribute("transform", `translate(${(x * 13).toFixed(3)} ${(y * 6).toFixed(3)}) rotate(${(x * 4.5).toFixed(3)} 635 558)`);
      face.current?.setAttribute("transform", `translate(${(x * 29).toFixed(3)} ${(y * 20).toFixed(3)})`);
    }
    function animate(time: number) {
      frame = 0;
      if (!visible || motion.matches) return;
      const elapsed = Math.min(50, previousTime ? time - previousTime : 16);
      previousTime = time;
      const follow = 1 - Math.exp(-elapsed / 105);
      current.x += (target.x - current.x) * follow;
      current.y += (target.y - current.y) * follow;
      paint();
      if (Math.abs(target.x - current.x) + Math.abs(target.y - current.y) > .001) {
        frame = window.requestAnimationFrame(animate);
      } else previousTime = 0;
    }
    function schedule() {
      if (!frame && visible && !motion.matches) frame = window.requestAnimationFrame(animate);
    }
    function reset() { target.x = 0; target.y = 0; schedule(); }
    function updateVisibility() {
      const bounds = button!.getBoundingClientRect();
      // Pause the mascot's motion once the hero scrolls out of view.
      visible = !document.hidden && bounds.bottom > 0 && bounds.top < window.innerHeight &&
        (!nextCard || nextCard.getBoundingClientRect().top > Math.max(0, bounds.top) + 50);
      button!.dataset.visible = String(visible);
      if (!visible || motion.matches) {
        window.cancelAnimationFrame(frame); frame = 0; previousTime = 0;
        target.x = target.y = current.x = current.y = 0;
        paint();
      }
    }
    function followPointer(event: PointerEvent) {
      if (!visible || motion.matches || event.pointerType === "touch") return;
      const bounds = button!.getBoundingClientRect();
      const size = Math.min(bounds.width, bounds.height);
      const eyeX = bounds.left + bounds.width / 2;
      const eyeY = bounds.top + (bounds.height - size) / 2 + size * .3;
      target.x = clamp((event.clientX - eyeX) / Math.max(240, window.innerWidth * .38));
      target.y = clamp((event.clientY - eyeY) / Math.max(220, window.innerHeight * .45));
      schedule();
    }
    const observer = new IntersectionObserver(updateVisibility);
    observer.observe(button);
    window.addEventListener("pointermove", followPointer, { passive: true });
    window.addEventListener("scroll", updateVisibility, { passive: true });
    window.addEventListener("resize", updateVisibility, { passive: true });
    window.addEventListener("blur", reset);
    document.addEventListener("pointerleave", reset);
    document.addEventListener("visibilitychange", updateVisibility);
    motion.addEventListener("change", updateVisibility);
    updateVisibility();
    return () => {
      observer.disconnect();
      window.cancelAnimationFrame(frame);
      if (replyTimer.current) clearTimeout(replyTimer.current);
      window.removeEventListener("pointermove", followPointer);
      window.removeEventListener("scroll", updateVisibility);
      window.removeEventListener("resize", updateVisibility);
      window.removeEventListener("blur", reset);
      document.removeEventListener("pointerleave", reset);
      document.removeEventListener("visibilitychange", updateVisibility);
      motion.removeEventListener("change", updateVisibility);
    };
  }, []);

  function greet() {
    setGreeting(true);
    if (replyTimer.current) clearTimeout(replyTimer.current);
    replyTimer.current = setTimeout(() => setGreeting(false), 1400);
  }

  return <div className="mascot-playground">
    <button ref={mascot} className="mascot-button" type="button" onClick={greet}
      aria-label="Sapa robot AI Builder" aria-describedby={`${uid}-help`}
      data-greeting={greeting ? "true" : "false"}>
      <svg className="mascot-svg" viewBox="0 0 1280 1280" aria-hidden="true" focusable="false">
        <defs>
          <clipPath id={`${uid}-body`}><path d="M0 530H404C431 548 506 564 632 564C761 564 838 548 865 530H1280V1280H0Z" /></clipPath>
          <clipPath id={`${uid}-head`}><path d="M0 0H1280V530H865C838 548 761 564 632 564C506 564 431 548 404 530H0Z" /></clipPath>
          <clipPath id={`${uid}-visor`}><rect x="434" y="300" width="388" height="195" rx="70" /></clipPath>
          <filter id={`${uid}-glow`} x="-50%" y="-70%" width="200%" height="240%"><feGaussianBlur stdDeviation="5" /><feMerge><feMergeNode /><feMergeNode in="SourceGraphic" /></feMerge></filter>
          <radialGradient id={`${uid}-shadow`}><stop stopColor="#101336" stopOpacity=".3" /><stop offset="1" stopColor="#101336" stopOpacity="0" /></radialGradient>
        </defs>
        <ellipse cx="640" cy="1200" rx="405" ry="60" fill={`url(#${uid}-shadow)`} />
        <g className="mascot-float"><g className="mascot-greet-bounce"><g ref={body} className="mascot-body">
          <rect x="492" y="520" width="272" height="100" rx="42" fill="#092555" />
          <image href={MASCOT_IMAGE} width="1280" height="1280" clipPath={`url(#${uid}-body)`} />
          <g ref={head} className="mascot-head"><g className="mascot-nod">
            <image href={MASCOT_IMAGE} width="1280" height="1280" clipPath={`url(#${uid}-head)`} />
            <g clipPath={`url(#${uid}-visor)`}><g ref={face} className="mascot-face" fill="none" stroke="#36f4ff" strokeLinecap="round" filter={`url(#${uid}-glow)`}>
              <g className="mascot-eye-blink" strokeWidth="18">
                <path className="mascot-eyes-normal" d="M491 381Q515 334 539 381M705 381Q729 334 753 381" />
                <path className="mascot-eyes-happy" d="M488 378Q515 324 542 378M702 378Q729 324 756 378" />
              </g>
              <path className="mascot-smile-normal" d="M592 431Q625 461 662 431" strokeWidth="10" />
              <path className="mascot-smile-happy" d="M582 423Q626 483 674 423Q630 440 582 423Z" fill="#36f4ff" strokeWidth="5" />
              <g className="mascot-cheeks" stroke="#f678ce" strokeWidth="9" opacity=".6"><path d="M481 419h19M745 419h19" /></g>
            </g></g>
          </g></g>
        </g></g></g>
        <g className="mascot-sparkles" fill="#99fff0"><path d="m224 278 11 34 34 11-34 11-11 34-11-34-34-11 34-11Zm820-93 13 39 39 13-39 13-13 39-13-39-39-13 39-13Z" /><circle cx="1090" cy="420" r="10" fill="#ed85c5" /><circle cx="181" cy="448" r="8" fill="#ed85c5" /></g>
      </svg>
    </button>
    <span id={`${uid}-help`} className="sr-only">Gerakkan kursor untuk mengajak robot melihat. Klik, sentuh, atau tekan Enter untuk menyapa.</span>
    <span className="mascot-reply" role="status" aria-live="polite">{greeting ? "Halo, future builder! ✦" : ""}</span>
  </div>;
}


const FOOTER_MASCOT_IMAGE = "data:image/webp;base64,";

function FooterMascot() {
  const button = useRef<HTMLButtonElement>(null);
  const napTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [working, setWorking] = useState(false);
  const uid = useId().replace(/:/g, "");
  const headShape = "M0 0H1280V475H892C845 517 773 540 630 540C487 540 411 519 366 476H0Z";
  const handShape = "M454 781C485 769 532 777 563 791C603 790 627 815 634 843L634 864C607 881 561 875 526 864L462 852Z";

  useEffect(() => {
    const element = button.current;
    if (!element) return;
    let inView = false;
    function sync() {
      const visible = inView && !document.hidden;
      element!.dataset.visible = String(visible);
      if (!visible) {
        if (napTimer.current) clearTimeout(napTimer.current);
        napTimer.current = null;
        setWorking(false);
      }
    }
    const observer = new IntersectionObserver(([entry]) => { inView = entry?.isIntersecting ?? false; sync(); }, { threshold: .05 });
    observer.observe(element);
    document.addEventListener("visibilitychange", sync);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", sync);
      if (napTimer.current) clearTimeout(napTimer.current);
    };
  }, []);

  function wakeUp() {
    if (napTimer.current) clearTimeout(napTimer.current);
    setWorking(true);
    // A little pretend productivity, then back to a well-earned nap.
    napTimer.current = setTimeout(() => { setWorking(false); napTimer.current = null; }, 9000);
  }

  return <div className="footer-mascot">
    <button ref={button} type="button" className="footer-bot-button" onClick={wakeUp}
      data-mode={working ? "working" : "sleeping"} data-visible="false"
      aria-label={working ? "Ajak robot AI Builder lanjut bekerja" : "Bangunkan robot AI Builder"}
      aria-describedby={`${uid}-footer-help`}>
      <svg viewBox="0 0 1280 1280" className="footer-bot-scene" aria-hidden="true" focusable="false">
        <defs>
          <clipPath id={`${uid}-footer-head`}><path d={headShape} /></clipPath>
          <clipPath id={`${uid}-footer-hand`}><path d={handShape} /></clipPath>
          <clipPath id={`${uid}-footer-body`}><path d={`M0 0H1280V1280H0Z ${headShape} ${handShape}`} clipRule="evenodd" /></clipPath>
          <filter id={`${uid}-footer-glow`} x="-60%" y="-70%" width="220%" height="240%"><feGaussianBlur stdDeviation="5" /><feMerge><feMergeNode /><feMergeNode in="SourceGraphic" /></feMerge></filter>
        </defs>
        <ellipse cx="640" cy="1205" rx="485" ry="38" fill="#07071c" opacity=".26" />
        <g className="footer-bot-body">
          <rect x="492" y="498" width="262" height="97" rx="36" fill="#102653" />
          <path d={handShape} fill="#1b335a" />
          <image href={FOOTER_MASCOT_IMAGE} width="1280" height="1280" clipPath={`url(#${uid}-footer-body)`} />
          <g className="footer-typing-hand"><image href={FOOTER_MASCOT_IMAGE} width="1280" height="1280" clipPath={`url(#${uid}-footer-hand)`} /></g>
        </g>
        <g className="footer-bot-head"><g className="footer-head-motion">
          <image href={FOOTER_MASCOT_IMAGE} width="1280" height="1280" clipPath={`url(#${uid}-footer-head)`} />
          <g className="footer-sleep-face" fill="none" stroke="#67e5f4" strokeLinecap="round" filter={`url(#${uid}-footer-glow)`}>
            <path d="M484 369Q511 388 538 369M704 369Q731 388 758 369" strokeWidth="12" />
            <ellipse cx="624" cy="425" rx="9" ry="5" strokeWidth="6" />
          </g>
          <g className="footer-work-face" fill="none" stroke="#36f4ff" strokeLinecap="round" filter={`url(#${uid}-footer-glow)`}>
            <g className="footer-work-eyes"><path d="M513 360v26M733 360v26" strokeWidth="18" /></g>
            <path d="M594 425Q624 448 654 425" strokeWidth="10" />
          </g>
        </g></g>
        <g className="footer-sleep-z" fill="#c7baed" fontFamily="Arial, sans-serif" fontWeight="700">
          <text className="footer-z footer-z-one" x="1010" y="335" fontSize="64">z</text>
          <text className="footer-z footer-z-two" x="1090" y="245" fontSize="83">z</text>
          <text className="footer-z footer-z-three" x="1150" y="135" fontSize="103">Z</text>
        </g>
        <g className="footer-laptop-activity" fill="none" stroke="#65fff0" strokeLinecap="round" filter={`url(#${uid}-footer-glow)`}>
          <path d="m722 692 399-37" strokeWidth="5" opacity=".5" />
          <path className="footer-code-line code-one" d="m766 740 61-6" strokeWidth="8" />
          <path className="footer-code-line code-two" d="m757 768 39-4" strokeWidth="6" />
          <path className="footer-code-line code-three" d="m747 795 57-5" strokeWidth="6" />
          <path className="footer-code-caret" d="m802 760-3 15" strokeWidth="5" />
        </g>
      </svg>
      <span className="footer-bot-hint" aria-hidden="true"><span className="footer-bot-dot" />{working ? "Lagi ngoding, kok!" : "Zzz… klik untuk bangunkan"}</span>
    </button>
    <span id={`${uid}-footer-help`} className="sr-only">Robot sedang bersantai. Klik, sentuh, atau tekan Enter untuk membangunkannya. Setelah sembilan detik, robot kembali beristirahat.</span>
    <span className="sr-only" role="status" aria-live="polite">{working ? "Robot bangun dan mulai mengetik di laptop." : "Robot sedang beristirahat."}</span>
  </div>;
}

type HomeSlots = { showcase: ReactNode; gallery: ReactNode; submission: ReactNode };

